using System;
using System.Collections.Generic;
using System.Linq;
namespace MaritimeLegend.Domain {
public partial class GameService : IMarketService,IProductionService {
        public MarketEntry Market(int city,string p){return S.cities[city].market.First(x=>x.product==p);}
        public double Specialty(int city,Product p){return C.ports[city].raw.Contains(p.id)?.78:1.08+(city+p.industry)%3*.06;}
        int Price(int city,Product p,int q,bool buy,double pressure){double reference=p.basePrice*C.market.qualityFactors[q]*Specialty(city,p)*Math.Exp(pressure);return Math.Max(1,(int)(buy?Math.Ceiling(reference*(1+C.market.spread/2)):Math.Floor(reference*(1-C.market.spread/2))));}
        public int Quote(int city,string p,int q,bool buy){return Price(city,C.Product(p),q,buy,Market(city,p).pressure);}
        public int Preview(int city,string id,int q,int n,bool buy){var m=Market(city,id);double p=m.pressure;int total=0;for(int i=0;i<n;i++){total+=Price(city,C.Product(id),q,buy,p);p=Clamp(p+(buy?1:-1)*C.market.pressureStep/C.market.referenceStock,C.market.pressureMin,C.market.pressureMax);}return total;}
        public string Trade(int city,string id,int q,int n,bool buy,Inventory inv){if(city<0||city>=8||q<0||q>5||n<1||n>999)return "交易参数无效";var p=C.Product(id);var m=Market(city,id);if(buy&&q!=3)return "常规市场仅出售品质3商品";if(buy&&m.stock<n)return "城市库存不足";if(!buy&&Inventory.Count(inv,id,q)<n)return "你的库存不足";if(buy&&Inventory.Weight(inv)+p.weight*n>inv.capacity)return "容量不足";if(!buy&&m.stock+n>C.market.maxStock)return "市场已饱和，请换港销售";int total=Preview(city,id,q,n,buy);if(buy&&S.gold<total)return "金币不足";if(buy){S.gold-=total;m.stock-=n;Inventory.Add(inv,id,q,n,city);m.bought+=n;}else{Inventory.Take(inv,id,n,q);S.gold+=total;m.stock+=n;m.sold+=n;}m.pressure=Clamp(m.pressure+(buy?1:-1)*n*C.market.pressureStep/C.market.referenceStock,C.market.pressureMin,C.market.pressureMax);S.trades++;S.cities[city].reputation+=Math.Max(1,n/5);Gain(3,Math.Min(n,20));Emit("trade");if(m.stock<5)Emit("shortage");CheckQuest();return (buy?"购入":"售出")+p.name+" ×"+n+"，"+(buy?"支出":"收入")+total+" 金币";}
        public void MarketHour(){foreach(var cs in S.cities)foreach(var m in cs.market){m.pressure*=Math.Pow(1-C.market.dailyReversion,1.0/24);var p=C.Product(m.product);if(p.category=="R"&&C.ports[cs.id].raw.Contains(p.id))m.stock=Math.Min((int)C.market.maxStock,m.stock+5);else if(p.category=="R"&&!C.ports[cs.id].raw.Contains(p.id)){m.stock=Math.Max(0,m.stock-3);}else if(p.category!="R"&&p.id!="flagship"){if(m.stock<15)m.stock++;else if(m.stock>15)m.stock--;}}}
        public string Contract(){if(S.worldHours>S.contractDeadline){S.contractProduct=(S.contractProduct+7)%C.products.Length;S.contractDeadline=S.worldHours+24;return "委托已更新，请查看新货物";}var p=C.products[S.contractProduct];if(Inventory.Count(S.cargo,p.id)<S.contractQuantity)return "船舱中需要 "+p.name+" ×"+S.contractQuantity;Inventory.Take(S.cargo,p.id,S.contractQuantity);int pay=(int)(p.basePrice*S.contractQuantity*1.6*(HasPartner(3)?1.08:1));S.gold+=pay;S.cities[S.city].reputation+=8;S.contracts++;S.contractProduct=(S.contractProduct+7)%C.products.Length;S.contractDeadline=S.worldHours+24;Emit("contract");return "商会支付 "+pay+" 金币，本城声望+8";}
}}
